import hashlib,json,platform,statistics,subprocess,sys,time
from datetime import datetime,timezone
from pathlib import Path
import torch
from rdkit import Chem
from anchor_dock.core.io import load_receptor_context
from anchor_dock.core.prepared import PreparedLigand
from anchor_dock.core.masks import normalize_pair_mask
from anchor_dock.core.scoring import PairwiseScorer,_weighted_pair_energy,positive_energy_curl
torch.set_num_threads(1)
rng=torch.Generator().manual_seed(20261030)
root=Path.cwd()
fixture=json.loads((root/'tests/fixtures/native_scoring.json').read_text())
p=fixture['cases']['10gs_ligand']
ligand=PreparedLigand.from_pdbqt(Chem.MolFromMolBlock(p['molblock'],removeHs=False),p['pdbqt'],serial_to_atom_index={int(k):v for k,v in p['serial_to_atom_index'].items()})
receptor=load_receptor_context(root/'examples/10gs/10gs_pocket.pdb',device='cpu')
def features(n):
 return {'radius_vina':torch.full((n,),1.9),'radius_vinardo':torch.full((n,),2.),'hydrophobic':torch.ones(n),'donor':torch.zeros(n),'acceptor':torch.zeros(n),'active':torch.ones(n,dtype=torch.bool)}
def dense_intra(prepared,xyz):
 d=torch.cdist(xyz,xyz)
 e=positive_energy_curl(_weighted_pair_energy(d,prepared.intramolecular_matrices,prepared.config),prepared.positive_energy_cap)
 m=normalize_pair_mask(prepared.intramolecular_mask,xyz.shape[0],xyz.shape[1],xyz.shape[1],device=xyz.device)
 return (e*m).sum((1,2))*.5
def run(fn,xyz,backward):
 if backward: torch.autograd.grad(fn(xyz).sum(),xyz)
 else:
  with torch.no_grad():fn(xyz)
def bench(functions,xyz,backward):
 for fn in functions.values():
  for _ in range(3):run(fn,xyz,backward)
 times={name:[] for name in functions}
 for repeat in range(15):
  order=list(functions) if repeat%2==0 else list(reversed(functions))
  for name in order:
   start=time.perf_counter_ns();run(functions[name],xyz,backward)
   times[name].append((time.perf_counter_ns()-start)/1e6)
 out={name:{'median_ms':statistics.median(v),'q25_ms':sorted(v)[3],'q75_ms':sorted(v)[11],'min_ms':min(v),'samples_ms':v} for name,v in times.items()}
 out['speedup_dense_over_sparse']=out['dense']['median_ms']/out['sparse']['median_ms']
 return out
cases=[('10gs_prepared',ligand.features(),ligand.coordinates().unsqueeze(0).expand(32,-1,-1).clone(),ligand.intramolecular_mask('cpu'),receptor.coords,receptor.features)]
for n in (128,256):
 xyz=torch.randn(32,n,3,generator=rng)*6;rec=torch.randn(512,3,generator=rng)*8
 for density in ('chain_nonlocal','random_10_percent'):
  if density=='chain_nonlocal':
   idx=torch.arange(n);mask=(idx[:,None]-idx[None,:]).abs()>3
  else:
   upper=torch.triu(torch.rand(n,n,generator=rng)<.1,diagonal=1);mask=upper|upper.T
  cases.append((f'synthetic_{n}_heavy_{density}',features(n),xyz,mask,rec,features(512)))
rows=[]
for label,feat,values,mask,rec,rf in cases:
 xyz=values.detach().clone().requires_grad_()
 ps={mode:PairwiseScorer('vina',intra_mode=mode,positive_energy_cap=1000.).prepare(feat,rec,rf,intramolecular_mask=mask) for mode in ('dense','sparse')}
 dense,sparse=ps['dense'],ps['sparse'];count=sparse.sparse_intra_pairs.shape[0]
 row={'case':label,'batch':xyz.shape[0],'atoms':xyz.shape[1],'heavy_atoms':sum(a.GetAtomicNum()!=1 for a in ligand.mol.GetAtoms()) if label=='10gs_prepared' else xyz.shape[1],'receptor_atoms':rec.shape[0],'directed_mask_entries':int(mask.sum()),'active_unordered_contributors':count,'dense_dynamic_pair_elements':xyz.shape[0]*xyz.shape[1]**2,'sparse_dynamic_pair_elements':xyz.shape[0]*count}
 with torch.no_grad():a=dense_intra(dense,xyz);b=sparse._sparse_intramolecular(xyz)
 ga=torch.autograd.grad(dense_intra(dense,xyz).sum(),xyz)[0];gb=torch.autograd.grad(sparse._sparse_intramolecular(xyz).sum(),xyz)[0]
 row['float32_max_abs_intra_energy_delta']=float((a-b).abs().max());row['float32_max_abs_coordinate_gradient_delta']=float((ga-gb).abs().max())
 for label2,fs in [('intra',{'dense':lambda x:dense_intra(dense,x),'sparse':sparse._sparse_intramolecular}),('full',{mode:p.search_energy for mode,p in ps.items()})]:
  for backward in (False,True):row[label2+('_forward_backward' if backward else '_forward')]=bench(fs,xyz,backward)
 rows.append(row)
 print(json.dumps({k:v for k,v in row.items() if not isinstance(v,dict)}),flush=True)
 print(json.dumps({key:{'dense_ms':row[key]['dense']['median_ms'],'sparse_ms':row[key]['sparse']['median_ms'],'speedup':row[key]['speedup_dense_over_sparse']} for key in ('intra_forward','intra_forward_backward','full_forward','full_forward_backward')}),flush=True)
base=subprocess.run(['git','show','HEAD:src/anchor_dock/core/scoring.py'],capture_output=True,check=True).stdout
out={'timestamp_utc':datetime.now(timezone.utc).isoformat(),'torch':torch.__version__,'python':sys.version,'platform':platform.platform(),'cuda_available':torch.cuda.is_available(),'threads':torch.get_num_threads(),'git_head':subprocess.run(['git','rev-parse','HEAD'],capture_output=True,text=True,check=True).stdout.strip(),'baseline_source_sha256':hashlib.sha256(base).hexdigest(),'candidate_source_sha256':hashlib.sha256((root/'src/anchor_dock/core/scoring.py').read_bytes()).hexdigest(),'dtype':'float32','seed':20261030,'positive_energy_cap':1000.,'warmup':3,'repeats':15,'procedure':'Alternate path order; preparation excluded; dense forward/reduction unchanged. Synthetic carbon-only geometry stress cases are not accuracy benchmarks. Full scorer includes identical dense inter work. No GPU/native parity or docking-quality claim.','cases':rows}
path=root.parents[1]/'anchor-checks/physical-intra-benchmark.json';path.write_text(json.dumps(out,indent=2)+'\n');print('EVIDENCE',path)
